import sys, math

def count_primes_below(n: int) -> int:
    """Return number of primes strictly less than n using sieve of Eratosthenes."""
    if n <= 2:
        return 0
    limit = n
    sieve = bytearray(b'\x01') * limit
    sieve[0:2] = b'\x00\x00'  # 0 and 1 are not prime
    max_p = int(math.isqrt(limit - 1))
    for p in range(2, max_p + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit:step] = b'\x00' * ((limit - 1 - start) // step + 1)
    return sum(sieve)

def solve(n: int = None):
    """If *n* is provided, return the count of primes below *n*.
    If *n* is omitted, read a single integer from standard input, print the answer,
    and also return it for convenience.
    """
    if n is None:
        data = sys.stdin.read().strip().split()
        if not data:
            return None
        n = int(data[0])
        result = count_primes_below(n)
        print(result)
        return result
    else:
        return count_primes_below(n)

