        sieve[0:2] = b'\x00\x00'
        max_p = int(math.isqrt(limit - 1))
        for p in range(2, max_p + 1):
            if sieve[p]:
                start = p * p
                step = p
                sieve[start:limit:step] = b'\x00' * ((limit - 1 - start) // step + 1)
        return sum(sieve)
    # Segmented sieve for larger n.
    sqrt_n = int(math.isqrt(n)) + 1
    # simple sieve up to sqrt_n to get base primes
    base = bytearray(b'\x01') * (sqrt_n + 1)
    base[0:2] = b'\x00\x00'
    for p in range(2, int(math.isqrt(sqrt_n)) + 1):
        if base[p]:
            step = p
            start = p * p
            base[start:sqrt_n+1:step] = b'\x00' * ((sqrt_n - start) // step + 1)
    base_primes = [i for i, is_p in enumerate(base) if is_p]
    segment_size = 1_000_000
    count = 0
    # Process segments [low, high)
    for low in range(2, n, segment_size):
