def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    tokens: list of strings containing integers and operators +, -, *, /.
    Division should truncate toward zero.
    """
    if not tokens:
        return 0
    stack = []
    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Python division truncates toward zero when using int() on the float result
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

