def solve(matrix):
    """Return determinant of a square integer matrix.
    An empty matrix has determinant 1.
    Uses recursive expansion; suitable for small matrices in tests.
    """
    # Empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square (defensive)
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Base cases
    if n == 1:
        return matrix[0][0]
    if n == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    det = 0
    for col in range(n):
        # build submatrix excluding first row and current column
        sub = [row[:col] + row[col+1:] for row in matrix[1:]]
        sign = -1 if col % 2 else 1
        det += sign * matrix[0][col] * solve(sub)
    return det
}

