import sys
import datetime

def weekday_name(year: int, month: int, day: int) -> str:
    """Return English weekday name for the given Gregorian date.
    Uses Python's datetime module which follows the proleptic Gregorian calendar.
    """
    dt = datetime.date(year, month, day)
    return dt.strftime('%A')

def solve(year=None, month=None, day=None):
    """If *year*, *month*, *day* are provided, return weekday name.
    Otherwise read three integers from stdin and print the result.
    """
    if year is None or month is None or day is None:
        data = sys.stdin.read().strip().split()
        if len(data) < 3:
            return None
        year, month, day = map(int, data[:3])
        result = weekday_name(year, month, day)
        print(result)
        return result
    else:
        return weekday_name(year, month, day)

def solve(year, month, day):
    # Zeller's congruence, Gregorian calendar, no library range limits
    if month < 3:
        month += 12
        year -= 1
    K = year % 100
    J = year // 100
    h = (day + (13 * (month + 1)) // 5 + K + K // 4 + J // 4 + 5 * J) % 7
    return ['Saturday', 'Sunday', 'Monday', 'Tuesday',
            'Wednesday', 'Thursday', 'Friday'][h]

