def solve(words, width):
    # Greedy word wrap: pack words into lines (single spaces) without
    # exceeding width, unless a single word alone is longer than width.
    lines = []
    cur = []
    cur_len = 0
    for w in words:
        if not cur:
            cur = [w]
            cur_len = len(w)
        elif cur_len + 1 + len(w) <= width:
            cur.append(w)
            cur_len += 1 + len(w)
        else:
            lines.append(' '.join(cur))
            cur = [w]
            cur_len = len(w)
    if cur:
        lines.append(' '.join(cur))
    return lines

